fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    input
        .into_iter()
        .map(|(a, b)| {
            if a == b {
                0
            } else if a < b {
                let d = b - a;
                // To increase by an even difference, we need two odd moves; 
                // to increase by an odd difference, just one odd move.
                if d % 2 != 0 { 1 } else { 2 }
            } else {
                let d = a - b;
                // To decrease by an odd difference, we need an extra odd increase
                // (so two moves); even difference can be done in one even move.
                if d % 2 == 0 { 1 } else { 2 }
            }
        })
        .collect()
}